222→// FindCheckpointUUID finds the UUID of the message containing the tool_result
223→// for the given tool use ID. Used for task checkpoint rewind.
224→// Returns the UUID and true if found, empty string and false otherwise.
225→func (c *ClaudeCodeAgent) FindCheckpointUUID(session *agent.AgentSession, toolUseID string) (string, bool) {
226→	if session == nil || len(session.NativeData) == 0 {
227→		return "", false
228→	}
229→
230→	lines, err := transcript.ParseFromBytes(session.NativeData)
231→	if err != nil {
232→		return "", false
233→	}
234→
235→	return FindCheckpointUUID(lines, toolUseID)
236→}
