 18→pub(crate) fn discover_handlers(config_layer_stack: Option<&ConfigLayerStack>) -> DiscoveryResult {
 19→    let Some(config_layer_stack) = config_layer_stack else {
 20→        return DiscoveryResult {
 21→            handlers: Vec::new(),
 22→            warnings: Vec::new(),
 23→        };
 24→    };
 25→
 26→    let mut handlers = Vec::new();
 27→    let mut warnings = Vec::new();
 28→    let mut display_order = 0_i64;
 29→
 30→    for layer in config_layer_stack.get_layers(
 31→        ConfigLayerStackOrdering::LowestPrecedenceFirst,
 32→        /*include_disabled*/ false,
 33→    ) {
 34→        let Some(folder) = layer.config_folder() else {
 35→            continue;
 36→        };
 37→        let source_path = match folder.join("hooks.json") {
 38→            Ok(source_path) => source_path,
 39→            Err(err) => {
 40→                warnings.push(format!(
 41→                    "failed to resolve hooks config path from {}: {err}",
 42→                    folder.display()
 43→                ));
 44→                continue;
 45→            }
 46→        };
 47→        if !source_path.as_path().is_file() {
 48→            continue;
 49→        }
 50→
 51→        let contents = match fs::read_to_string(source_path.as_path()) {
 52→            Ok(contents) => contents,
 53→            Err(err) => {
 54→                warnings.push(format!(
 55→                    "failed to read hooks config {}: {err}",
 56→                    source_path.display()
 57→                ));
 58→                continue;
 59→            }
 60→        };
 61→
 62→        let parsed: HooksFile = match serde_json::from_str(&contents) {
 63→            Ok(parsed) => parsed,
 64→            Err(err) => {
 65→                warnings.push(format!(
 66→                    "failed to parse hooks config {}: {err}",
 67→                    source_path.display()
 68→                ));
 69→                continue;
 70→            }
 71→        };
 72→
 73→        for group in parsed.hooks.pre_tool_use {
 74→            append_group_handlers(
 75→                &mut handlers,
 76→                &mut warnings,
 77→                &mut display_order,
 78→                source_path.as_path(),
 79→                codex_protocol::protocol::HookEventName::PreToolUse,
 80→                matcher_pattern_for_event(
 81→                    codex_protocol::protocol::HookEventName::PreToolUse,
 82→                    group.matcher.as_deref(),
 83→                ),
 84→                group.hooks,
 85→            );
 86→        }
