157→	parseHookType(rawHooks, "SessionStart", &sessionStart)
158→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
159→	parseHookType(rawHooks, "Stop", &stop)
160→
161→	sessionStart = removeEntireHooks(sessionStart)
162→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
163→	stop = removeEntireHooks(stop)
164→
165→	marshalHookType(rawHooks, "SessionStart", sessionStart)
166→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
167→	marshalHookType(rawHooks, "Stop", stop)
168→
169→	if len(rawHooks) > 0 {
170→		hooksJSON, err := json.Marshal(rawHooks)
171→		if err != nil {
172→			return fmt.Errorf("failed to marshal hooks: %w", err)
173→		}
174→		topLevel["hooks"] = hooksJSON
175→	} else {
176→		delete(topLevel, "hooks")
177→	}
