189→// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
190→func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
191→	repoRoot, err := paths.WorktreeRoot(ctx)
192→	if err != nil {
193→		repoRoot = "."
194→	}
195→
196→	hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
197→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
198→	if err != nil {
199→		return false
200→	}
201→
202→	var hooksFile HooksFile
203→	if err := json.Unmarshal(data, &hooksFile); err != nil {
204→		return false
205→	}
206→
207→	return hookCommandExists(hooksFile.Hooks.Stop, "entire hooks codex stop") ||
208→		hookCommandExists(hooksFile.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex stop")
209→}
210→
211→// --- Helpers ---
212→
213→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) {
214→	if data, ok := rawHooks[hookType]; ok {
215→		//nolint:errcheck,gosec // Intentionally ignoring parse errors
216→		json.Unmarshal(data, target)
217→	}
218→}
219→
220→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
221→	if len(groups) == 0 {
222→		delete(rawHooks, hookType)
223→		return
224→	}
225→	data, err := json.Marshal(groups)
226→	if err != nil {
227→		return
228→	}
229→	rawHooks[hookType] = data
230→}
231→
232→func hookCommandExists(groups []MatcherGroup, command string) bool {
233→	for _, group := range groups {
234→		for _, hook := range group.Hooks {
235→			if hook.Command == command {
236→				return true
237→			}
238→		}
239→	}
240→	return false
241→}
242→
243→func addHook(groups []MatcherGroup, command string) []MatcherGroup {
244→	entry := HookEntry{
245→		Type:    "command",
246→		Command: command,
247→		Timeout: 30,
248→	}
249→
250→	// Add to an existing group with null matcher, or create a new one
251→	for i, group := range groups {
252→		if group.Matcher == nil {
253→			groups[i].Hooks = append(groups[i].Hooks, entry)
254→			return groups
255→		}
256→	}
257→	return append(groups, MatcherGroup{
258→		Matcher: nil,
259→		Hooks:   []HookEntry{entry},
260→	})
261→}
262→
263→func isEntireHook(command string) bool {
264→	for _, prefix := range entireHookPrefixes {
265→		if strings.HasPrefix(command, prefix) {
266→			return true
267→		}
268→	}
269→	return false
270→}
271→
272→func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
273→	result := make([]MatcherGroup, 0, len(groups))
274→	for _, group := range groups {
275→		filtered := make([]HookEntry, 0, len(group.Hooks))
276→		for _, hook := range group.Hooks {
277→			if !isEntireHook(hook.Command) {
278→				filtered = append(filtered, hook)
279→			}
280→		}
281→		if len(filtered) > 0 {
282→			group.Hooks = filtered
283→			result = append(result, group)
284→		}
285→	}
286→	return result
287→}
