	require.NoError(t, err)
	require.Contains(t, string(data), "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex session-start")
}

func TestInstallHooks_Force(t *testing.T) {
	t.Parallel()
	env := testutil.NewHookTestEnv(t)
	ag := &CodexAgent{}

	// Install first
	_, err := ag.InstallHooks(env.Ctx, false, false)
	require.NoError(t, err)

	// Force reinstall removes old and adds new
	count, err := ag.InstallHooks(env.Ctx, false, true)
	require.NoError(t, err)
	require.Equal(t, 3, count)
}

func TestUninstallHooks(t *testing.T) {
	t.Parallel()
	env := testutil.NewHookTestEnv(t)
	ag := &CodexAgent{}

	// Install first
	_, err := ag.InstallHooks(env.Ctx, false, false)
	require.NoError(t, err)

