package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "codex" {
		return
	}
	Register(&Codex{})
	RegisterGate("codex", 2)
}

// Codex implements the E2E Agent interface for OpenAI's Codex CLI.
type Codex struct{}

func (c *Codex) Name() string               { return "codex" }
func (c *Codex) Binary() string             { return "codex" }
func (c *Codex) EntireAgent() string        { return "codex" }
func (c *Codex) PromptPattern() string      { return `>` }
func (c *Codex) TimeoutMultiplier() float64 { return 1.5 }

func (c *Codex) Bootstrap() error {
	// On CI, ensure OPENAI_API_KEY is available.
	if os.Getenv("CI") == "" {
		return nil
	}
	if os.Getenv("OPENAI_API_KEY") == "" {
		return nil
	}
	return nil
}

func (c *Codex) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{"overloaded", "rate limit", "rate_limit", "503", "529", "ECONNRESET", "ETIMEDOUT"} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

// codexHome creates an isolated CODEX_HOME for a test run.
// This keeps trust entries and feature flags out of the real ~/.codex/config.toml.
// Auth still works via OPENAI_API_KEY env var (checked before CODEX_HOME).
func codexHome() (string, func(), error) {
	dir, err := os.MkdirTemp("", "codex-home-*")
	if err != nil {
		return "", nil, err
	}
	return dir, func() { _ = os.RemoveAll(dir) }, nil
}

func (c *Codex) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	home, cleanup, err := codexHome()
	if err != nil {
		return Output{}, fmt.Errorf("create codex home: %w", err)
	}
	defer cleanup()

	args := []string{
		"exec",
		"--dangerously-bypass-approvals-and-sandbox",
	}
	if cfg.Model != "" {
		args = append(args, "-m", cfg.Model)
	}
	args = append(args, prompt)

	displayArgs := []string{
		"exec",
		"--dangerously-bypass-approvals-and-sandbox",
	}
	if cfg.Model != "" {
		displayArgs = append(displayArgs, "-m", cfg.Model)
	}
	displayArgs = append(displayArgs, fmt.Sprintf("%q", prompt))

	env := append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME"),
		"CODEX_HOME="+home,
	)

	// entire enable wrote trust + feature flag via CODEX_HOME during SetupRepo.
	// But SetupRepo's CODEX_HOME pointed at a different temp dir. We need to
	// re-seed trust for this isolated home so Codex loads .codex/hooks.json.
	absDir, _ := filepath.Abs(dir)
	if err := seedCodexHome(home, absDir); err != nil {
		return Output{}, fmt.Errorf("seed codex home: %w", err)
	}

	cmd := exec.CommandContext(ctx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = env
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err = cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (c *Codex) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("codex-test-%d", time.Now().UnixNano())

	home, cleanup, err := codexHome()
	if err != nil {
		return nil, fmt.Errorf("create codex home: %w", err)
	}

	absDir, _ := filepath.Abs(dir)
	if err := seedCodexHome(home, absDir); err != nil {
		cleanup()
		return nil, fmt.Errorf("seed codex home: %w", err)
	}

	env := filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME")

	s, err := NewTmuxSession(name, dir, nil, "env",
		"CODEX_HOME="+home,
		"codex", "--dangerously-bypass-approvals-and-sandbox",
	)
	if err != nil {
		cleanup()
		return nil, err
	}
	s.OnClose(cleanup)

	// Forward API key if present
	for _, e := range env {
		if strings.HasPrefix(e, "OPENAI_API_KEY=") {
			_ = s.Send("export " + e)
		}
	}

	if _, err := s.WaitFor(c.PromptPattern(), 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for codex prompt: %w", err)
	}

	return s, nil
}

// seedCodexHome writes trust + feature flag config so Codex loads the
// project's .codex/ layer. This mirrors what `entire enable` does via
// ensureProjectTrusted, but into the isolated E2E CODEX_HOME.
func seedCodexHome(home, projectDir string) error {
	config := fmt.Sprintf("[features]\ncodex_hooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", projectDir)
	if err := os.MkdirAll(home, 0o750); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600)
}

package codex

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

// setupTestEnv creates a temp dir, sets CWD and CODEX_HOME for test isolation.
// Cannot be parallel (uses t.Chdir and t.Setenv which are process-global).
func setupTestEnv(t *testing.T) string {
	t.Helper()
	tempDir := t.TempDir()
	t.Chdir(tempDir)
	t.Setenv("CODEX_HOME", filepath.Join(tempDir, ".codex-home"))
	return tempDir
}

func TestInstallHooks_CreatesConfig(t *testing.T) {
	tempDir := setupTestEnv(t)
	codexHome := os.Getenv("CODEX_HOME")

	ag := &CodexAgent{}
	count, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)
	require.Equal(t, 3, count) // SessionStart, UserPromptSubmit, Stop

	// Verify hooks.json was created in the repo
	hooksPath := filepath.Join(tempDir, ".codex", HooksFileName)
	data, err := os.ReadFile(hooksPath)
	require.NoError(t, err)
	require.Contains(t, string(data), "entire hooks codex session-start")
	require.Contains(t, string(data), "entire hooks codex user-prompt-submit")
	require.Contains(t, string(data), "entire hooks codex stop")

	// Verify project-level config.toml enables codex_hooks feature (per-repo)
	projectConfig := filepath.Join(tempDir, ".codex", configFileName)
	projectData, err := os.ReadFile(projectConfig)
	require.NoError(t, err)
	require.Contains(t, string(projectData), "codex_hooks = true")
	require.Contains(t, string(projectData), "[features]")

	// Verify user-level config.toml trusts this project
	userConfig := filepath.Join(codexHome, configFileName)
	userData, err := os.ReadFile(userConfig)
	require.NoError(t, err)
	require.Contains(t, string(userData), `trust_level = "trusted"`)
	require.Contains(t, string(userData), tempDir)
}

func TestInstallHooks_Idempotent(t *testing.T) {
	setupTestEnv(t)

	ag := &CodexAgent{}

	count1, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)
	require.Equal(t, 3, count1)

	count2, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)
	require.Equal(t, 0, count2)
}

func TestInstallHooks_LocalDev(t *testing.T) {
	tempDir := setupTestEnv(t)

	ag := &CodexAgent{}
	count, err := ag.InstallHooks(context.Background(), true, false)
	require.NoError(t, err)
	require.Equal(t, 3, count)

	hooksPath := filepath.Join(tempDir, ".codex", HooksFileName)
	data, err := os.ReadFile(hooksPath)
	require.NoError(t, err)
	require.Contains(t, string(data), "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex session-start")
}

func TestInstallHooks_Force(t *testing.T) {
	setupTestEnv(t)

	ag := &CodexAgent{}

	_, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)

	count, err := ag.InstallHooks(context.Background(), false, true)
	require.NoError(t, err)
	require.Equal(t, 3, count)
}

func TestUninstallHooks(t *testing.T) {
	setupTestEnv(t)

	ag := &CodexAgent{}

	_, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)

	err = ag.UninstallHooks(context.Background())
	require.NoError(t, err)

	require.False(t, ag.AreHooksInstalled(context.Background()))
}

func TestAreHooksInstalled_NoFile(t *testing.T) {
	setupTestEnv(t)

	ag := &CodexAgent{}
	require.False(t, ag.AreHooksInstalled(context.Background()))
}

func TestAreHooksInstalled_WithHooks(t *testing.T) {
	setupTestEnv(t)

	ag := &CodexAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)

	require.True(t, ag.AreHooksInstalled(context.Background()))
}

func TestInstallHooks_PreservesExistingHooksJSON(t *testing.T) {
	tempDir := setupTestEnv(t)

	ag := &CodexAgent{}

	codexDir := filepath.Join(tempDir, ".codex")
	require.NoError(t, os.MkdirAll(codexDir, 0o750))
	existingConfig := `{
		"hooks": {
			"PreToolUse": [
				{
					"matcher": "^Bash$",
					"hooks": [
						{"type": "command", "command": "my-custom-hook"}
					]
				}
			]
		}
	}`
	require.NoError(t, os.WriteFile(filepath.Join(codexDir, HooksFileName), []byte(existingConfig), 0o600))

	_, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)

	data, err := os.ReadFile(filepath.Join(codexDir, HooksFileName))
	require.NoError(t, err)
	require.Contains(t, string(data), "my-custom-hook")
	require.Contains(t, string(data), "entire hooks codex stop")
}

func TestInstallHooks_PreservesExistingUserConfig(t *testing.T) {
	setupTestEnv(t)
	codexHome := os.Getenv("CODEX_HOME")

	require.NoError(t, os.MkdirAll(codexHome, 0o750))
	existingConfig := "model = \"gpt-4.1\"\n"
	require.NoError(t, os.WriteFile(filepath.Join(codexHome, configFileName), []byte(existingConfig), 0o600))

	ag := &CodexAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	require.NoError(t, err)

	configData, err := os.ReadFile(filepath.Join(codexHome, configFileName))
	require.NoError(t, err)
	require.Contains(t, string(configData), "model = \"gpt-4.1\"")
	require.Contains(t, string(configData), `trust_level = "trusted"`)
}

